SELECT * FROM ( SELECT anchor.id AS anchor_id,'exact' AS kind,anchor.file_sha256 AS group_key, COUNT(*) AS total,SUM(candidate.gallery_status='PENDING') AS pending,SUM(candidate.gallery_status='APPROVED') AS approved, SUM(CASE WHEN THEN 1 ELSE 0 END) AS reviewable, SUM(CASE WHEN candidate.gallery_status='PENDING' AND THEN 1 ELSE 0 END) AS reviewable_pending FROM destination_comment_images anchor JOIN destination_comments ac ON ac.id=anchor.comment_id JOIN destination_comment_images candidate ON candidate.analysis_destination_id=ac.destination_id AND candidate.file_sha256=anchor.file_sha256 JOIN destination_comments c ON c.id=candidate.comment_id AND c.destination_id=ac.destination_id WHERE ac.destination_id=#{destinationId} AND AND AND anchor.id=(SELECT MIN(first_photo.id) FROM destination_comment_images first_photo JOIN destination_comments first_comment ON first_comment.id=first_photo.comment_id WHERE first_photo.analysis_destination_id=ac.destination_id AND first_comment.destination_id=ac.destination_id AND first_photo.file_sha256=anchor.file_sha256 AND ) GROUP BY anchor.id,anchor.file_sha256 HAVING COUNT(*) > 1 AND SUM(CASE WHEN
AND AND candidate.gallery_status=#{status} THEN 1 ELSE 0 END) > 0 UNION ALL SELECT anchor.id AS anchor_id,'similar' AS kind,CAST(anchor.id AS CHAR) AS group_key, COUNT(*) AS total,SUM(candidate.gallery_status='PENDING') AS pending,SUM(candidate.gallery_status='APPROVED') AS approved, SUM(CASE WHEN THEN 1 ELSE 0 END) AS reviewable, SUM(CASE WHEN candidate.gallery_status='PENDING' AND THEN 1 ELSE 0 END) AS reviewable_pending FROM destination_comment_images anchor JOIN destination_comments ac ON ac.id=anchor.comment_id JOIN destination_comment_images candidate ON candidate.analysis_destination_id=ac.destination_id JOIN destination_comments c ON c.id=candidate.comment_id AND c.destination_id=ac.destination_id WHERE ac.destination_id=#{destinationId} AND AND AND (candidate.id=anchor.id OR ()) GROUP BY anchor.id HAVING SUM(candidate.id > anchor.id) > 0 AND SUM(CASE WHEN
AND candidate.gallery_status=#{status} THEN 1 ELSE 0 END) > 0 ) workflow_groups ORDER BY reviewable_pending DESC,reviewable DESC,anchor_id,kind LIMIT #{limit} OFFSET #{offset}

SELECT i.id, i.comment_id, c.user_id, i.gallery_status, i.file_sha256 AS sha256
FROM destination_comment_images i JOIN destination_comments c ON c.id=i.comment_id
WHERE c.destination_id=#{destinationId} AND i.analysis_destination_id=#{destinationId}
  AND i.analysis_state IN ('READY','HASH_ONLY') AND i.id IN
#{id}
ORDER BY i.id FOR UPDATE

