UPDATE destination_comment_images i
SET i.analysis_state = 'READY', i.analysis_version = 1, i.analysis_token = NULL,
  i.analysis_lease_until = NULL, i.analysis_next_attempt = NULL, i.analyzed_at = CURRENT_TIMESTAMP,
  i.analysis_destination_id = #{job.destinationId}, i.file_sha256 = #{result.sha256},
  i.perceptual_hash = #{result.dHash}, i.hash_band_0 = #{b0}, i.hash_band_1 = #{b1},
  i.hash_band_2 = #{b2}, i.hash_band_3 = #{b3}, i.pixel_width = #{result.width},
  i.pixel_height = #{result.height}, i.mean_brightness = #{result.brightness},
  i.sharpness = #{result.sharpness}, i.quality_flags = #{result.qualityFlags}
WHERE i.id = #{job.id} AND i.image_url = #{job.imageUrl} AND i.comment_id = #{job.commentId}
  AND i.analysis_state = 'RUNNING' AND i.analysis_token = #{token}

UPDATE destination_comment_images SET analysis_state = 'FAILED', analysis_token = NULL,
  analysis_lease_until = NULL, analysis_next_attempt = DATE_ADD(CURRENT_TIMESTAMP, INTERVAL 10 MINUTE)
WHERE id = #{id} AND analysis_state = 'RUNNING' AND analysis_token = #{token}

UPDATE destination_comment_images i
SET i.analysis_state = 'HASH_ONLY', i.analysis_version = 1, i.analysis_token = NULL,
  i.analysis_lease_until = NULL, i.analysis_next_attempt = NULL, i.analyzed_at = CURRENT_TIMESTAMP,
  i.analysis_destination_id = #{job.destinationId}, i.file_sha256 = #{sha256}
WHERE i.id = #{job.id} AND i.image_url = #{job.imageUrl} AND i.comment_id = #{job.commentId}
  AND i.analysis_state = 'RUNNING' AND i.analysis_token = #{token}
